CREATE OR REPLACE FUNCTION public.notice_admin_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE actor uuid; receiver uuid; label text; BEGIN IF TG_TABLE_NAME='messages' THEN actor:=NEW.sender_id; receiver:=NEW.receiver_id; label:='కొత్త సందేశం నమోదైంది'; ELSE actor:=NEW.user_id; label:=CASE WHEN TG_TABLE_NAME='posts' THEN 'కొత్త ప్రకటన నమోదైంది' ELSE 'ప్రకటనకు గంట నమోదైంది' END; END IF; INSERT INTO public.notifications(user_id,message) SELECT user_id,label FROM public.user_roles WHERE role='admin' AND user_id<>actor AND (receiver IS NULL OR user_id<>receiver); RETURN NEW; END $$;